import { Component } from 'react'
import PropTypes from 'prop-types'
import { VerifiedDocSubmitStyle, VerifiedDocSubmitBodyStyle } from './index.style'
import { VERIFIED_DOC_SVG } from '../../../../../images'
import { VERIFICATION_LANG } from '../../lang'
import { Button, CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import FullPageModal from '../../../../../components/FullPageModal'

class VerifiedDocSubmitModal extends Component {
  static propTypes = {
    history: PropTypes.object,
    showModal: PropTypes.bool,
    email: PropTypes.string,
    msg: PropTypes.string,
    onCloseModal: PropTypes.func
  }

  handleOkay = () => {
    // we replace the current history, because if user press back
    // button then he will not land to verification screen
    this.props.history.replace('/profile')
    this.props.onCloseModal()
  }

  render () {
    const { showModal, email, msg } = this.props
    return (
      <VerifiedDocSubmitStyle>
        <FullPageModal
          showModal={showModal}
          onCloseModal={this.handleOkay}
          header={VERIFICATION_LANG.dataVerificationProcessed}
        >
          <VerifiedDocSubmitStyle>
            <VerifiedDocSubmitBodyStyle>
              <div className='verified-submit-img'>
                <img src={VERIFIED_DOC_SVG} alt='' />
              </div>
              <CustomText
                size='20px'
                weight={800}
                bottom='20px'
                color='#000000'
              >
                {VERIFICATION_LANG.verificationBeingProcessed}
              </CustomText>
              <CustomText
                size='16px'
                lineHeight={1.5}
                textAlign='center'
                color={AgentColorPallette.fontDarkerGrey}
                className='verified-statement-width'
              >
                {msg}
              </CustomText>
              <CustomText
                size='16px'
                lineHeight={1.5}
                color={AgentColorPallette.fontDarkerGrey}
              >
                {VERIFICATION_LANG.verifyEmailStatement}
              </CustomText>
              <CustomText
                size='16px'
                bottom='20px'
                color={AgentColorPallette.darkGold}
              >
                {email}
              </CustomText>
              <Button
                className='verified-tutup-btn'
                onClick={this.handleOkay}
              >
                {LANG_STRINGS.okay}
              </Button>
            </VerifiedDocSubmitBodyStyle>
          </VerifiedDocSubmitStyle>
        </FullPageModal>
      </VerifiedDocSubmitStyle>
    )
  }
}

export default VerifiedDocSubmitModal
