import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

// ktp and Npwp context for verification
export const ktpNpwpContext = createContext()

// context provider
export const KtpNpwpContextProvider = (props) => {
  return (
    <ktpNpwpContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </ktpNpwpContext.Provider>
  )
}

// use context Value
export const useKtpNpwpContextValue = () => useContext(ktpNpwpContext)
