import { Component } from 'react'
import PropTypes from 'prop-types'
import CustomText from '../../../../../components/CustomText'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { UploadDocStyle } from './index.style'
import NumericInput from '../../../../../components/NumericInput'
import DocUpload from '../../../../../components/DocUpload'

class UploadDocument extends Component {
  static propTypes = {
    title: PropTypes.string,
    type: PropTypes.string,
    onDocUpload: PropTypes.func,
    imgUrl: PropTypes.string,
    index: PropTypes.string,
    docError: PropTypes.string,
    inputError: PropTypes.string,
    isLoading: PropTypes.bool,
    verifiedDocData: PropTypes.object,
    onInputChange: PropTypes.func
  }

  handleInputChange = (data) => {
    const { type, onInputChange } = this.props
    onInputChange({ value: data, type })
  }

  render () {
    const {
      title, index, placeholder, type, docError,
      onDocUpload, imgUrl, isLoading, inputError, verifiedDocData = {}
    } = this.props
    return (
      <UploadDocStyle paddingBtm={type === 'npwp' ? '20%' : 0}>
        <CustomText
          size='16px;'
          weight='800'
          bottom='20px;'
          color={AgentColorPallette.black}
        >
          {index}&nbsp;{title}
        </CustomText>
        <DocUpload
          name={type}
          error={docError}
          onUploadDocCall={onDocUpload}
          imgUrl={imgUrl}
          isVerified={verifiedDocData.verified}
          hideCross={verifiedDocData.status === 'SUBMITTED'}
          isLoading={isLoading}
        />
        <NumericInput
          name={type}
          errorField={inputError}
          placeholder={placeholder}
          defaultValue={verifiedDocData.number}
          disabled={verifiedDocData.verified || (verifiedDocData.status === 'SUBMITTED')}
          onChange={this.handleInputChange}
          className='ktp-npwp-number'
          wrapperClass='input-wrapper'
        />
      </UploadDocStyle>
    )
  }
}

export default UploadDocument
