import { Component } from 'react'
import PropTypes from 'prop-types'
import { UploadDocBtmStyle } from './index.style'
import { Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

class UploadDocBtm extends Component {
  static propTypes = {
    disabled: PropTypes.bool,
    onSubmitDetails: PropTypes.func
  }

  handleGoToBack = () => {
    this.props.history.goBack()
  }

  render () {
    const { onSubmitDetails, disabled } = this.props
    return (
      <UploadDocBtmStyle>
        <Button
          type='button'
          key='verifyBtn'
          color={AgentColorPallette.white}
          backgroundColor={AgentColorPallette.cyanBlue}
          onClick={this.handleGoToBack}
          className='verify-doc-btn'
        >
          {LANG_STRINGS.cancel}
        </Button>
        <Button
          type='button'
          key='verifySubmit'
          color={AgentColorPallette.fontDarkGrey}
          handleClick={onSubmitDetails}
          disabled={disabled}
          className='verify-doc-btn'
        >
          {LANG_STRINGS.save}
        </Button>
      </UploadDocBtmStyle>
    )
  }
}

export default UploadDocBtm
