import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Container } from '../../../../components'
import { ERROR_LANG, LANG_STRINGS } from '../../../../lang'
import { get } from 'lodash/object'
import VerifyEmail from '../components/VerifyEmail'
import UploadDocument from '../components/UploadDocument'
import { KTP_NPWP_DOCS } from '../constants'
import UploadDocBtm from '../components/UploadDocBtm'

import VerifiedDocSubmitModal from '../components/VerifiedDocSubmitModal'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { useGetVerificationDoc, useResetKtpNpwpState, useSubmitVerificationDoc, useUploadVerificationDoc } from '../state/hooks/useKtpState'
import { useGlobalContextValue } from '../../../../contextProvider/GlobalContext'
import { typeValid } from '../../../../helpers/validations'
import ShowSnackbar from '../../../../components/ShowNotification'
import { VERIFICATION_LANG } from '../lang'

function KtpNpwpVerificationContainer (props) {
  const { history } = props
  const [state, setState] = useState({
    loaderName: '',
    ktp: {},
    npwp: {}
  })
  const [error, setError] = useState({})
  const [snackbar, setSnackbar] = useState({
    show: false,
    error: false,
    msg: ''
  })
  const [showVerifyDocModal, setShowVerifyDocModal] = useState({
    show: false,
    msg: ''
  })
  const [btnDisabled, setBtnDisabled] = useState(true)
  const [{ getAgentDetailData, isGojekAgent }] = useGlobalContextValue()
  const [{
    GET_VERIFICATION_DOCS_LOADER, SUBMIT_VERIFICATION_DOCS_LOADER,
    UPLOAD_DOC_LOADER
  }, dispatchLoader] = useLoaderContextValue()
  const [{
    uploadDocStatus, submitVerificationDocsStatus
  }, dispatchError] = useErrorContextValue()
  const verificationForm = useMemo(() => {
    const ktpForm = [...KTP_NPWP_DOCS]
    if (isGojekAgent) {
      ktpForm.splice(1, 1)
    }
    return ktpForm
  }, [isGojekAgent])
  const that = useRef({
    ktp: '',
    npwp: ''
  })
  const currentSubmitted = useRef({})
  const isDocSubmitted = false

  const [{ getVerificationDocsData = {} }, getVerificationDocRequest] = useGetVerificationDoc()
  const [{ uploadDocData = {} }, uploadKtpNpwpRequest] = useUploadVerificationDoc()
  const [, submitVerificationDocRequest] = useSubmitVerificationDoc()
  const resetKtpNpwpState = useResetKtpNpwpState()

  const checkedInitialData = useCallback((map) => {
    let msg = ''
    const { ktp, npwp } = map
    if (ktp && (ktp.status === 'SUBMITTED') && npwp && (ktp.status === 'SUBMITTED')) {
      msg = VERIFICATION_LANG.yourKtpAndNpwpVerification
    } else if (ktp && (ktp.status === 'SUBMITTED')) {
      msg = VERIFICATION_LANG.yourKtpInVerificationProcess
    } else if (npwp && (npwp.status === 'SUBMITTED')) {
      msg = VERIFICATION_LANG.yourNpwpCurrentlyInProcess
    }
    if (msg) {
      setShowVerifyDocModal({
        show: true,
        msg: msg
      })
    }
    return !!msg
  }, [])

  // we are initially store the documents in the map object for easy access
  const verifyDocumentsData = useMemo(() => {
    const map = {}
    if (getVerificationDocsData.document?.length) {
      getVerificationDocsData.document.forEach(item => {
        const itemType = item.document_type.toLowerCase()
        map[itemType] = {
          ...item
        }
      })

      if (checkedInitialData(map)) return map
    }
    // this set state update the ktp and npwp
    // to local state from the context
    setState(prevState => ({
      ...prevState,
      ...map
    }))
    return map
  }, [getVerificationDocsData.document, checkedInitialData])

  const updateSnackBar = useCallback((text, error) => {
    setSnackbar({
      error,
      show: true,
      msg: text
    })
    setTimeout(() => {
      setSnackbar({
        show: false
      })
    }, 3000)
  }, [])

  useEffect(() => {
    // this effect use to get verification Data if any
    if (GET_VERIFICATION_DOCS_LOADER === undefined) {
      getVerificationDocRequest()
    }
  }, [GET_VERIFICATION_DOCS_LOADER, getVerificationDocRequest])

  const getNotificationMsg = useCallback(() => {
    // this function returns the notifications msgs
    const { ktp, npwp } = currentSubmitted.current
    const isKtpVerified = verifyDocumentsData.ktp?.verified
    const isNpwpVerified = verifyDocumentsData.npwp?.verified
    let msg = ''

    if (ktp && npwp) {
      msg = VERIFICATION_LANG.yourKtpAndNpwpVerification
    } else if (npwp && (!verifyDocumentsData.npwp || (verifyDocumentsData.npwp.status === 'REJECTED'))) {
      msg = VERIFICATION_LANG.npwpVerificationWithInOneDay
    } else if (ktp && (!npwp || isNpwpVerified)) {
      msg = VERIFICATION_LANG.yourKtpInVerificationProcess
    } else if (npwp && isKtpVerified && !verifyDocumentsData.npwp) {
      msg = VERIFICATION_LANG.yourNpwpCurrentlyInProcess
    }
    return msg
  }, [verifyDocumentsData])

  useEffect(() => {
    // this effect called when agent move from the page
    // work as unmount function
    return () => {
      dispatchLoader(updateLoader({
        GET_VERIFICATION_DOCS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    // this effect used if any verification data
    if (uploadDocData.document_type && uploadDocStatus === 'success') {
      setState(prevState => ({
        ...prevState,
        [uploadDocData.document_type.toLowerCase()]: {
          ...uploadDocData
        }
      }))
      resetKtpNpwpState({
        uploadDocData: {}
      })
      dispatchError(resetError({
        uploadDocStatus: undefined
      }))
    }

    if (submitVerificationDocsStatus === 'success') {
      setShowVerifyDocModal({
        show: true,
        msg: getNotificationMsg()
      })
      dispatchError(resetError({
        submitVerificationDocsStatus: undefined
      }))
    } else if (submitVerificationDocsStatus) {
      if (typeof submitVerificationDocsStatus === 'string') {
        updateSnackBar(submitVerificationDocsStatus, true)
      } else {
        updateSnackBar(ERROR_LANG.errorOnAgainSubmitDoc, true)
      }

      dispatchError(resetError({
        submitVerificationDocsStatus: undefined
      }))
    }

    if (getAgentDetailData.ktp_no && !that.current.ktp) {
      that.current.ktp = getAgentDetailData.ktp_no
      that.current.npwp = getAgentDetailData.npwp_no
    }
  }, [
    uploadDocData, uploadDocStatus, dispatchError,
    submitVerificationDocsStatus, getAgentDetailData,
    getNotificationMsg, resetKtpNpwpState, updateSnackBar
  ])

  const handleBtnEnable = useCallback((data) => {
    if (btnDisabled) {
      setBtnDisabled((prevState) => {
        let isBtnDisabled = isGojekAgent ? !(data.type === 'ktp' && data.value) : !((data.type === 'npwp') && data.value)
        if (btnDisabled && (data.type || data.name)) {
          isBtnDisabled = false
        }
        return isBtnDisabled
      })
    }
  }, [isGojekAgent, btnDisabled])

  const handleDocUpload = useCallback((data) => {
    // handle Img upload
    if (data.file) {
      // if file exist that means need
      // to upload the file
      const formData = new FormData()
      formData.append('file', data.file)
      setState(prevState => ({
        ...prevState,
        loaderName: data.name
      }))
      uploadKtpNpwpRequest({
        body: formData,
        name: data.name
      })
      handleBtnEnable(data)
    } else {
      // remove the file from the local store
      setState(prevState => ({
        ...prevState,
        [data.name]: {}
      }))
    }
  }, [uploadKtpNpwpRequest, handleBtnEnable])

  const handleInputChange = useCallback((data) => {
    // handle input change
    that.current[data.type] = data.value
    handleBtnEnable(data)
  }, [handleBtnEnable])

  const validateDocsData = useCallback(() => {
    let error = false
    function updateError (key, type, value) {
      // this is used to update the error state
      setError(prevError => {
        const errorKey = prevError[key] || {}
        errorKey[type] = value
        return {
          ...prevError,
          [key]: errorKey
        }
      })
    }

    for (const key in that.current) {
      const item = that.current[key]
      const status = verifyDocumentsData[key]?.status
      if (key === 'npwp' && !state[key].id && !item) continue
      if (!state[key].id) {
        // here we are checking the document id
        // if doc empty then show error on doc side also
        error = true

        updateError(key, 'docError', key)
        const picError = key === 'ktp' ? LANG_STRINGS.uploadIdCardPic : LANG_STRINGS.uploadNPWPPic
        updateSnackBar(picError, true)
        break
      } else if (status === 'REJECTED' && (verifyDocumentsData[key]?.id === state[key]?.id)) {
        updateError(key, 'docError', key)
        error = true
        const picError = key === 'ktp' ? LANG_STRINGS.uploadNewKtpPhoto : LANG_STRINGS.uploadNewNpwpPhoto
        updateSnackBar(picError, true)
        break
      } else {
        updateError(key, 'docError', '')
      }

      if (!typeValid(key, (item || ''))) {
        // check the KTP Number value here
        const inputError = (key === 'ktp' ? LANG_STRINGS.ktpError : LANG_STRINGS.npwpError)
        updateError(key, 'inputError', key)
        updateSnackBar(inputError, true)
        error = true
        break
      } else {
        updateError(key, 'inputError', '')
      }
    }
    return error
  }, [state, updateSnackBar, verifyDocumentsData])

  const handleVerifySubmit = useCallback(() => {
    // handle submit the documents
    if (validateDocsData()) {
      // show error if id is not present
      return
    }
    const documents = [
      {
        document_type: 'KTP',
        document_uuid: state.ktp.id
      }
    ]
    const body = {
      ktp_no: that.current.ktp
    }
    currentSubmitted.current.ktp = true

    if (state.npwp?.id) {
      documents.push({
        document_type: 'NPWP',
        document_uuid: state.npwp.id
      })
      body.npwp_no = that.current.npwp
      currentSubmitted.current.npwp = true
    }
    submitVerificationDocRequest({
      body: {
        ...body,
        documents
      }
    })
  }, [
    submitVerificationDocRequest, state,
    validateDocsData
  ])

  const handleCloseModal = useCallback(() => {
    setShowVerifyDocModal({
      show: false
    })
  }, [setShowVerifyDocModal])

  return (
    <Container
      title={LANG_STRINGS.verificationData}
      hideBottomTabs
      loader={GET_VERIFICATION_DOCS_LOADER || SUBMIT_VERIFICATION_DOCS_LOADER}
    >
      <VerifyEmail
        isVerifiedEmail={getVerificationDocsData.is_email_verified}
        email={getVerificationDocsData.email}
        hideEdit={isGojekAgent}
        hideVerificationBtn={isGojekAgent}
      />
      {
        verificationForm.map((item, index) => (
          <UploadDocument
            key={`doc_${index + 1}`}
            index={`${index + 2}.`}
            imgUrl={state[item.type]?.url}
            docError={error[item.type]?.docError}
            inputError={error[item.type]?.inputError}
            isLoading={UPLOAD_DOC_LOADER && state.loaderName === item.type}
            verifiedDocData={{
              ...verifyDocumentsData[item.type],
              number: get(getAgentDetailData, `${item.type}_no`, '')
            }}
            onDocUpload={handleDocUpload}
            onInputChange={handleInputChange}
            {...item}
          />
        ))
      }
      {
        !(
          (isGojekAgent && (getAgentDetailData.is_ktp_verified || isDocSubmitted)) ||
          (getAgentDetailData.is_ktp_verified && getAgentDetailData.is_verified)
        ) &&
        (
          <UploadDocBtm
            history={history}
            disabled={btnDisabled}
            onSubmitDetails={handleVerifySubmit}
          />
        )
      }
      {
        showVerifyDocModal.show && (
          <VerifiedDocSubmitModal
            showModal={showVerifyDocModal.show}
            history={history}
            msg={showVerifyDocModal.msg}
            email={getVerificationDocsData.email}
            onCloseModal={handleCloseModal}
          />
        )
      }
      {
        snackbar.show && (
          <ShowSnackbar
            show={snackbar.show}
            text={snackbar.msg}
            error={snackbar.error}
          />
        )
      }
    </Container>
  )
}

export default KtpNpwpVerificationContainer
