import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useKtpNpwpContextValue } from '../../context'
import { getVerificationDoc, submitVerificationDoc, uploadKtpNpwpDoc, resetKtpNpwpState } from '../actions'

export const useKtpNpwpServiceCall = (actionsCall = () => {}) => {
  const [ktpNpwpState, dispatch] = useKtpNpwpContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback((payload = {}) => {
    callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [ktpNpwpState, request]
}

// get verification Data call
export const useGetVerificationDoc = () => useKtpNpwpServiceCall(getVerificationDoc)

// submit verification Data call
export const useSubmitVerificationDoc = () => useKtpNpwpServiceCall(submitVerificationDoc)

// upload ktp and Npwp Doc img
export const useUploadVerificationDoc = () => useKtpNpwpServiceCall(uploadKtpNpwpDoc)

// reset ktp and Npwp states
export const useResetKtpNpwpState = () => {
  const [, dispatch] = useKtpNpwpContextValue()

  const resetState = (payload) => {
    dispatch(resetKtpNpwpState(payload))
  }
  return resetState
}
