import { KTP_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case KTP_ACTIONS.GET_VERIFICATION_DOCS:
    case KTP_ACTIONS.UPLOAD_DOC:
    case KTP_ACTIONS.SUBMIT_VERIFICATION_DOCS:
    case KTP_ACTIONS.RESET_KTP_NPWP_STATE:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
