import { Component } from 'react'
import PropTypes from 'prop-types'
import { get } from 'lodash/object'
import { connect } from 'react-redux'
import { NotificationManager } from 'react-notifications'
import {
  VerifyEmailStyle, EmailInputWrapper, VerifyButtonWrapper,
  VerifyEmailEdit, VerifyEmailEditIcon
} from './index.style'
import { CustomText, Button } from '../../../../../components'
import verificationAction from '../../../../../redux/verification/actions'
import { LANG_STRINGS } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import CircularLoader from '../../../../../components/CircularLoader'
import { VERIFICATION_LANG } from '../../lang'

const {
  updateUserEmail, resetVerificationStore,
  getVerificationDocs, sendEmailVerifyLink
} = verificationAction
class VerifyEmail extends Component {
  static propTypes = {
    isVerifiedEmail: PropTypes.bool,
    hideEdit: PropTypes.bool,
    hideVerificationBtn: PropTypes.bool,
    email: PropTypes.string
  }

  constructor (props) {
    super(props)
    this.state = {
      email: '',
      isEditEmail: false
    }
  }

  componentWillReceiveProps (nextProps) {
    const { updateEmailMsg, sendEmailVerifyMsg } = nextProps
    if (updateEmailMsg) {
      this.setState({
        isEditEmail: false
      })
      this.props.getVerificationDocs()
      NotificationManager.success(VERIFICATION_LANG.updateEmailSuccessful)
    }

    if (sendEmailVerifyMsg) {
      NotificationManager.success(VERIFICATION_LANG.sendEmailVerifyLink)
    }
    this.props.resetVerificationStore(['updateEmailMsg', 'sendEmailVerifyMsg'])
  }

  handleVerifyEmail = (e) => {
    // this function used to send email
    this.props.sendEmailVerifyLink({
      email: this.props.email
    })
  }

  handleEmailChange = e => {
    this.setState({
      email: e.target.value
    })
  }

  handleEditClick = () => {
    // this function used to show edit email and close edit
    // email
    this.setState((prevState) => ({
      isEditEmail: !prevState.isEditEmail,
      email: get(this.props, 'email', '')
    }))
  }

  handleSubmitEdit = () => {
    // this function update the user email
    this.props.updateUserEmail({
      email: this.state.email
    })
  }

  render () {
    const {
      isVerifiedEmail, editEmailLoading, sendEmailVerifyLinkLoader,
      hideEdit, hideVerificationBtn
    } = this.props
    const userEmail = get(this.props, 'email', '')
    const { isEditEmail, email } = this.state
    return (
      <VerifyEmailStyle>
        <CustomText
          size='16px'
          weight='800'
          top='20px'
          color={AgentColorPallette.black}
        >
          1. {LANG_STRINGS.verifyEmail}
        </CustomText>
        {
          !isEditEmail && (
            <>
              <CircularLoader isLoading={sendEmailVerifyLinkLoader} className='edit-email-form-container'>
                <VerifyEmailEdit>
                  <CustomText size='14px' color={AgentColorPallette.fontSecondary}>
                    {userEmail}
                  </CustomText>
                  {
                    isVerifiedEmail
                      ? (
                        <i className='fas fa-check verify-check' />
                      )
                      : (
                        !hideEdit && (
                          <VerifyEmailEditIcon onClick={this.handleEditClick}>
                            <i className='fas fa-pen' />
                          </VerifyEmailEditIcon>
                        )
                      )
                  }
                </VerifyEmailEdit>
                {
                  !isVerifiedEmail && !hideVerificationBtn && (
                    <VerifyButtonWrapper>
                      <Button
                        type='button'
                        key='submit'
                        className='send-verification-btn'
                        color={AgentColorPallette.fontDarkGrey}
                        onClick={this.handleVerifyEmail}
                      >
                        {LANG_STRINGS.sendVerificationEmail}
                      </Button>
                    </VerifyButtonWrapper>
                  )
                }
              </CircularLoader>
            </>
          )
        }
        {
          isEditEmail && (
            <>
              <CircularLoader isLoading={editEmailLoading} className='edit-email-form-container'>
                <form className='email-form' name='emailEdit'>
                  <EmailInputWrapper
                    type='email'
                    name='email'
                    inputmode='email'
                    value={email}
                    onChange={this.handleEmailChange}
                  />
                </form>
                <VerifyButtonWrapper>
                  <Button
                    type='button'
                    key='cancelBtn'
                    color={AgentColorPallette.white}
                    backgroundColor={AgentColorPallette.cyanBlue}
                    onClick={this.handleEditClick}
                    className='cancelBtn'
                  >
                    {LANG_STRINGS.cancel}
                  </Button>
                  <Button
                    type='button'
                    key='submit'
                    color={AgentColorPallette.fontDarkGrey}
                    onClick={this.handleSubmitEdit}
                    className='cancelBtn'
                  >
                    {LANG_STRINGS.save}
                  </Button>
                </VerifyButtonWrapper>
              </CircularLoader>
            </>
          )
        }
      </VerifyEmailStyle>
    )
  }
}

export default connect(
  (state) => ({
    updateEmailMsg: state.Verification.updateEmailMsg,
    editEmailLoading: state.Loading.EDIT_EMAIL,
    sendEmailVerifyMsg: state.Verification.sendEmailVerifyMsg,
    sendEmailVerifyLinkData: state.Verification.sendEmailVerifyLinkData,
    sendEmailVerifyLinkLoader: state.Loading.SEND_EMAIL_VERIFY_LINK
  }),
  {
    updateUserEmail,
    getVerificationDocs,
    sendEmailVerifyLink,
    resetVerificationStore
  }
)(VerifyEmail)
