import { Component } from 'react'
import PropTypes from 'prop-types'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import 'react-notifications/lib/notifications.css'
import { DocUploadStyle, ErrorCrossStyle } from './index.style'
import { CAMERA_ICON } from '../../images'
import { LANG_STRINGS } from '../../lang'
import CircularLoader from '../CircularLoader'
import { AgentColorPallette } from '../../configs/colorPallete'
import { INPUT_FILE_TYPE } from '../../constants/file'

class DocUpload extends Component {
  // you can remove the same img by calling the same function
  // as called to submit the file data
  static propTypes = {
    onUploadDocCall: PropTypes.func,
    name: PropTypes.string,
    imgUrl: PropTypes.string,
    error: PropTypes.string,
    isVerified: PropTypes.bool,
    hideCross: PropTypes.bool,
    isLoading: PropTypes.bool,
  }

  handleUpload = () => {
    // this function check is selected image is valid
    const { name, onUploadDocCall } = this.props
    const file = document.getElementById(name)
    if ('files' in file) {
      if (file.files[0]) {
        if (file.files[0].size > 11000000) {
          NotificationManager.error(LANG_STRINGS.fileSizeLarge)
        } else {
          NotificationManager.info(LANG_STRINGS.uploadStart)
          onUploadDocCall({ file: file.files[0], name: name })
        }
      }
    }
  }

  handleRemoveImg = () => {
    // this function remove the image
    const { name, onUploadDocCall } = this.props
    onUploadDocCall({ name: name })
  }

  render() {
    const {
      name,
      error,
      isLoading,
      className,
      loaderClassName,
      imgUrl = '',
      isVerified,
      hideCross,
    } = this.props
    return (
      <CircularLoader isLoading={isLoading} className={loaderClassName}>
        <DocUploadStyle img={imgUrl} error={name === error} className={className}>
          {!imgUrl && (
            <>
              <img src={CAMERA_ICON} alt="camera-icon" width="50" />
              <input
                type="file"
                id={name}
                name={name}
                onChange={this.handleUpload}
                accept={INPUT_FILE_TYPE.IMAGE}
              />
            </>
          )}
          {imgUrl && isVerified ? (
            <ErrorCrossStyle bg={AgentColorPallette.green}>
              <i className="fa fa-check" />
            </ErrorCrossStyle>
          ) : imgUrl && !hideCross ? (
            <ErrorCrossStyle onClick={this.handleRemoveImg}>
              <i className="fas fa-times" />
            </ErrorCrossStyle>
          ) : null}
        </DocUploadStyle>
        <NotificationContainer />
      </CircularLoader>
    )
  }
}

export default DocUpload
